    """스트리밍 중 진행 상황을 stderr 한 줄로 표시한다.

    thinking(사고)과 답변 생성이 오래 걸릴 때 화면이 조용해 보이는 문제를 막는다.
    """
    state = {"reasoning": 0, "content": 0}

